<body>
<div class="game">
  <header>
    <div>
      <h1>Gate Agent Rush</h1>
      <div class="hint">Sort each passenger into the correct boarding group before the gate closes.</div>
    </div>
    <div class="stats">
      <div class="pill">Time: <span id="time">45</span>s</div>
      <div class="pill">Score: <span id="score">0</span></div>
      <div class="pill">Boarded: <span id="boarded">0</span>/18</div>
    </div>
  </header>

  <div class="feedback" id="feedback">Press Start Boarding</div>

  <main class="board">
    <section class="panel passenger">
      <div class="ticket">
        <div class="name" id="pName">Passenger</div>
        <div class="detail" id="pSeat">Seat --</div>
        <div class="detail">Boarding Group</div>
        <div class="group" id="pGroup">?</div>
        <div class="hint">Click a lane or use keys 1, 2, 3</div>
      </div>
    </section>

    <section class="panel">
      <div class="lanes" id="lanes"></div>
    </section>
  </main>

  <div class="controls">
    <button id="start">Start Boarding</button>
    <button class="secondary" id="restart">Restart</button>
  </div>
</div>

<div class="overlay" id="overlay">
  <h2>Gate Agent Rush ✈️</h2>
  <p>Passengers appear one at a time. Send them to Group A, B, or C. Correct sorts earn points. Mistakes cost time.</p>
  <p>Controls: click/tap a lane, or press 1 / 2 / 3.</p>
  <button id="play">Start Boarding</button>
</div>

<script>
(() => {
  const names = [
    "M. Carter","J. Patel","A. Nguyen","S. Rivera","D. Brooks","L. Kim",
    "T. Morgan","R. Ellis","N. Price","C. Wong","B. Adams","K. Davis",
    "P. Reed","E. Stone","H. Ortiz","V. Shah","G. Mills","Y. Tan"
  ];
  const groups = ["A","B","C"];
  const seats = ["2A","4C","8D","11F","14B","18A","20C","22D","24F","28B","31A","33C"];

  const lanesEl = document.getElementById("lanes");
  const timeEl = document.getElementById("time");
  const scoreEl = document.getElementById("score");
  const boardedEl = document.getElementById("boarded");
  const feedback = document.getElementById("feedback");
  const overlay = document.getElementById("overlay");
  const pName = document.getElementById("pName");
  const pSeat = document.getElementById("pSeat");
  const pGroup = document.getElementById("pGroup");

  let deck = [];
  let current = null;
  let score = 0;
  let boarded = 0;
  let time = 45;
  let running = false;
  let timer = null;
  let locked = false;

  function makeDeck(){
    const list = names.map(name => ({
      name,
      seat: seats[Math.floor(Math.random() * seats.length)],
      group: groups[Math.floor(Math.random() * groups.length)]
    }));
    return list.sort(() => Math.random() - 0.5);
  }

  function renderLanes(){
    lanesEl.innerHTML = "";
    groups.forEach((g, i) => {
      const div = document.createElement("div");
      div.className = "lane";
      div.tabIndex = 0;
      div.setAttribute("role", "button");
      div.setAttribute("aria-label", "Send passenger to boarding group " + g);
      div.innerHTML = `
        <b>Group ${g}</b>
        <span class="key">${i + 1}</span>
        <div class="queue" id="q${g}" aria-label="Passengers boarded in group ${g}"></div>
      `;
      div.addEventListener("click", () => choose(g));
      div.addEventListener("keydown", e => {
        if(e.key === "Enter" || e.key === " "){
          e.preventDefault();
          choose(g);
        }
      });
      lanesEl.appendChild(div);
    });
  }

  function nextPassenger(){
    locked = false;
    if(boarded >= 18 || time <= 0 || deck.length === 0){
      end();
      return;
    }
    current = deck.shift();
    pName.textContent = current.name;
    pSeat.textContent = "Seat " + current.seat;
    pGroup.textContent = current.group;
  }

  function choose(g){
    if(!running || !current || locked) return;
    locked = true;

    if(g === current.group){
      score += 100 + Math.max(0, time);
      boarded++;
      feedback.textContent = "Correct boarding!";
      feedback.className = "feedback good";

      const q = document.getElementById("q" + g);
      if(q){
        const m = document.createElement("span");
        m.className = "mini";
        m.textContent = current.group;
        q.appendChild(m);
      }
    } else {
      score = Math.max(0, score - 35);
      time = Math.max(0, time - 3);
      feedback.textContent = "Wrong lane. " + current.name + " was Group " + current.group + ".";
      feedback.className = "feedback bad";
    }

    update();
    setTimeout(nextPassenger, 220);
  }

  function update(){
    timeEl.textContent = time;
    scoreEl.textContent = score;
    boardedEl.textContent = boarded;
  }

  function start(){
    clearInterval(timer);
    deck = makeDeck().concat(makeDeck());
    current = null;
    score = 0;
    boarded = 0;
    time = 45;
    running = true;
    locked = false;

    overlay.classList.add("hidden");
    feedback.textContent = "Boarding open!";
    feedback.className = "feedback warn";

    renderLanes();
    update();
    nextPassenger();

    timer = setInterval(() => {
      if(!running) return;
      time--;
      update();
      if(time <= 0) end();
    }, 1000);
  }

  function end(){
    if(!running && overlay.classList.contains("hidden") === false) return;
    running = false;
    locked = true;
    clearInterval(timer);

    const success = boarded >= 18;
    const rating = success
      ? (score >= 2300 ? "First Class Finish" : "Clean Boarding")
      : (boarded >= 12 ? "Nearly Closed" : "Gate Delay");

    overlay.innerHTML = `
      <h2>${success ? "Flight Boarded ✅" : "Boarding Closed ⏱️"}</h2>
      <p>${rating}</p>
      <p>Boarded: ${boarded}/18</p>
      <p>Final Score: ${score}</p>
      <button id="playAgain">Play Again</button>
    `;
    overlay.classList.remove("hidden");
    document.getElementById("playAgain").addEventListener("click", start);

    pName.textContent = "Passenger";
    pSeat.textContent = "Seat --";
    pGroup.textContent = "?";
  }

  document.getElementById("start").addEventListener("click", start);
  document.getElementById("restart").addEventListener("click", start);
  document.getElementById("play").addEventListener("click", start);

  document.addEventListener("keydown", e => {
    if(e.key === "1") choose("A");
    if(e.key === "2") choose("B");
    if(e.key === "3") choose("C");
    if(e.key === "Enter" && !running) start();
  });

  renderLanes();
  update();
})();
</script>
</body>
</html>
